1	package meter
2	
3	import (
4		"sort"
5		"sync"
6		"time"
7	)
8	
9	// Service 是订阅、用量与账单的本地内存服务。
10	// 单个 *Service 可被多个 goroutine 并发使用：重复提交只会生效一次。
11	type Service struct {
12		mu       sync.Mutex
13		now      func() time.Time
14		accounts map[string]*account
15		plans    map[string]Plan
16	}
17	
18	type subRecord struct {
19		activatedAt time.Time
20		// terms 是本订阅段套餐条件的唯一事实来源，按生效月份升序保存，
21		// 首条为开通当月适用的开通快照，之后每条对应一次已生效的换套餐。
22		// 当前套餐标识、当前完整条件与任意历史账期的条件都统一由
23		// termsForPeriod 从中取出，开通与换套餐生效时只需在这里追加一份快照。
24		terms []termsEntry
25		// pending 尚未生效的换套餐安排，每账户至多一条；nil 表示无安排。
26		pending *PlanChange
27		// cancelEnd 已安排的终止时刻（取消请求时刻的下一个 UTC 自然月月初）。
28		// 非 nil 且尚未到达时为等待取消状态；到达后本订阅段终止并移入 history。
29		cancelEnd *time.Time
30		// endedAt 已终止订阅段的实际终止时刻；当前有效段为 nil。
31		endedAt *time.Time
32	}
33	
34	type eventRecord struct {
35		at     time.Time
36		qty    int64
37		period Month
38	}
39	
40	type billRecord struct {
41		bill Bill
42	}
43	
44	type paymentRecord struct {
45		period Month
46		amount int64
47		// balance 与 settled 是本笔付款首次成功登记完成时账单的余额与付清状态。
48		// 完全相同的重报原样返回该历史结果，不随后续付款或账单当前状态变化。
49		balance int64
50		settled bool
51	}
52	
53	type account struct {
54		id       string
55		sub      *subRecord
56		history  []*subRecord
57		events   map[string]eventRecord
58		usage    map[Month]int64
59		bills    map[Month]*billRecord
60		payments map[string]paymentRecord
61	}
62	
63	// NewService 创建一个以系统时钟判断“当前时刻”的服务。
64	func NewService() *Service {
65		return NewServiceWithClock(time.Now)
66	}
67	
68	// NewServiceWithClock 创建使用自定义时钟的服务，便于测试账期与截止时刻。
69	func NewServiceWithClock(now func() time.Time) *Service {
70		if now == nil {
71			now = time.Now
72		}
73		return &Service{
74			now:      now,
75			accounts: make(map[string]*account),
76			plans:    make(map[string]Plan),
77		}
78	}
79	
80	func (s *Service) nowUTC() time.Time {
81		return s.now().UTC()
82	}
83	
84	// CreateAccount 创建业务账户。账户标识必须非空且唯一。
85	func (s *Service) CreateAccount(id string) error {
86		if id == "" {
87			return invalidf("account id is empty")
88		}
89		s.mu.Lock()
90		defer s.mu.Unlock()
91		if _, ok := s.accounts[id]; ok {
92			return ErrAccountExists
93		}
94		s.accounts[id] = &account{
95			id:       id,
96			events:   make(map[string]eventRecord),
97			usage:    make(map[Month]int64),
98			bills:    make(map[Month]*billRecord),
99			payments: make(map[string]paymentRecord),
100		}
101		return nil
102	}
103	
104	func validatePlan(p Plan) error {
105		if p.ID == "" {
106			return invalidf("plan id is empty")
107		}
108		if p.MonthlyFee < 0 || p.IncludedUnits < 0 || p.OveragePrice < 0 {
109			return invalidf("plan %q has negative amount or quantity", p.ID)
110		}
111		if p.TaxRateBasisPoints < 0 || p.TaxRateBasisPoints > 10000 {
112			return invalidf("plan %q tax rate %d out of [0,10000]", p.ID, p.TaxRateBasisPoints)
113		}
114		return nil
115	}
116	
117	// CreatePlan 创建套餐。金额单位为分，税率为万分比且在 [0,10000]。
118	func (s *Service) CreatePlan(p Plan) error {
119		if err := validatePlan(p); err != nil {
120			return err
121		}
122		s.mu.Lock()
123		defer s.mu.Unlock()
124		if _, ok := s.plans[p.ID]; ok {
125			return ErrPlanExists
126		}
127		s.plans[p.ID] = p
128		return nil
129	}
130	
131	// UpdatePlan 更新套餐当前条件。只影响之后开通的订阅，
132	// 已开通订阅继续使用开通时保存的快照。
133	func (s *Service) UpdatePlan(p Plan) error {
134		if err := validatePlan(p); err != nil {
135			return err
136		}
137		s.mu.Lock()
138		defer s.mu.Unlock()
139		if _, ok := s.plans[p.ID]; !ok {
140			return ErrPlanNotFound
141		}
142		s.plans[p.ID] = p
143		return nil
144	}
145	
146	// Subscribe 为账户开通订阅，并保存当时的套餐条件快照。
147	// 每个账户只允许一份有效订阅；从 activatedAt 起接收用量，
148	// 首月仍收完整月费并提供完整额度。
149	//
150	// activatedAt 可以晚于当前时刻，即提前登记一份尚未生效的订阅：登记会被保留，
151	// 但在实际开通时刻到达前 Status 的 Subscribed 为 false、CurrentTerms 为零值，
152	// 也没有待换套餐安排与待取消终止时刻；此期间再次开通仍返回
153	// ErrSubscriptionExists，安排换套餐、登记取消返回 ErrSubscriptionNotActivated。
154	// 判断以实际开通时刻为界（按同一瞬间比较，带时区的开通时间结果一致），不按
155	// 开通月份提前生效；到达开通时刻后查询即显示有效订阅与登记时保存的完整套餐
156	// 条件快照，等待期间修改套餐定义不改变该快照。
157	//
158	// 订阅终止（按月取消到达终止时刻）后可用本入口重新开通：activatedAt 不得早于
159	// 上一段订阅的终止时刻；重新开通保存当时的套餐条件，当月仍收完整月费、给完整
160	// 额度。重新开通不重置账户内事件与付款标识，也不清除旧欠费。同样允许登记未来
161	// 的重新开通时刻：旧订阅已结束、新订阅尚未开始的间隔中查询不显示任何生效套餐，
162	// 历史用量与账单继续可查。
163	func (s *Service) Subscribe(accountID, planID string, activatedAt time.Time) error {
164		if accountID == "" {
165			return invalidf("account id is empty")
166		}
167		if planID == "" {
168			return invalidf("plan id is empty")
169		}
170		if activatedAt.IsZero() {
171			return invalidf("activated at is zero")
172		}
173		s.mu.Lock()
174		defer s.mu.Unlock()
175		acc, ok := s.accounts[accountID]
176		if !ok {
177			return ErrAccountNotFound
178		}
179		now := s.nowUTC()
180		// 与其他入口保持一致：先让已到期的换套餐/取消落入历史。
181		s.settleLocked(acc, now)
182		plan, ok := s.plans[planID]
183		if !ok {
184			return ErrPlanNotFound
185		}
186		if acc.sub != nil {
187			return ErrSubscriptionExists
188		}
189		activated := activatedAt.UTC()
190		// 重新开通时刻不得早于上一段订阅的终止时刻。
191		if n := len(acc.history); n > 0 {
192			if activated.Before(*acc.history[n-1].endedAt) {
193				return ErrResubscribeBeforeEnd
194			}
195		}
196		acc.sub = &subRecord{
197			activatedAt: activated,
198			// 开通快照即条件时间线首条：当前条件与历史出账都从这里取。
199			terms: []termsEntry{{
200				effective: MonthOf(activated),
201				terms:     termsOf(plan),
202			}},
203		}
204		return nil
205	}
206	
207	// nextMonth 返回 period 的下一个 UTC 自然月。
208	func nextMonth(period Month) Month {
209		return MonthOf(period.End())
210	}
211	
212	// settleLocked 让当前订阅段中已到生效时刻的换套餐安排落入条件历史，
213	// 并在到达取消终止时刻时把当前段标记终止、移入 acc.history。
214	// 到达月初零点（或终止时刻）即生效，无需先上报用量或生成账单；即使中间若干月
215	// 没有调用服务，再次进入时也会在此一次性补齐。调用时持有 s.mu。
216	//
217	// 开通时刻尚未到达的订阅段只是提前登记：它尚未生效，既没有已生效的套餐条件，
218	// 也不可能有待换套餐安排或待取消终止时刻，因此在到达开通时刻前不做任何处理，
219	// 尤其不能按开通月份让条件“提前生效”。
220	func (s *Service) settleLocked(acc *account, now time.Time) {
221		sub := acc.sub
222		if sub == nil || now.Before(sub.activatedAt) {
223			return
224		}
225		current := MonthOf(now)
226		for sub.pending != nil && !current.Before(sub.pending.EffectivePeriod) {
227			// 换套餐生效只需向条件时间线追加一份锁定快照；
228			// 当前套餐标识与当前条件都由该时间线统一导出，无需另行更新。
229			sub.terms = append(sub.terms, termsEntry{
230				effective: sub.pending.EffectivePeriod,
231				terms:     sub.pending.Terms,
232			})
233			sub.pending = nil
234		}
235		if sub.cancelEnd != nil && !now.Before(*sub.cancelEnd) {
236			end := *sub.cancelEnd
237			sub.cancelEnd = nil
238			sub.pending = nil
239			sub.endedAt = &end
240			acc.history = append(acc.history, sub)
241			acc.sub = nil
242		}
243	}
244	
245	// activeSegmentAtLocked 返回覆盖时刻 at 的订阅段：activatedAt <= at < end。
246	// 优先检查当前段，再按时间倒序检查历史段。调用时持有 s.mu。
247	func activeSegmentAtLocked(acc *account, at time.Time) *subRecord {
248		if cur := acc.sub; cur != nil && !at.Before(cur.activatedAt) {
249			if cur.cancelEnd == nil || at.Before(*cur.cancelEnd) {
250				return cur
251			}
252		}
253		for i := len(acc.history) - 1; i >= 0; i-- {
254			h := acc.history[i]
255			if !at.Before(h.activatedAt) && at.Before(*h.endedAt) {
256				return h
257			}
258		}
259		return nil
260	}
261	
262	// termsForPeriod 在订阅段 sub 中返回指定账期当时适用的套餐条件快照。
263	// 条件时间线按生效月份升序，取不晚于 period 的最后一条；当前条件、
264	// 是否与当前套餐相同、历史账单出账全部经过这里，因此同一账期永远得到
265	// 同一份完整条件（月费、额度、超额单价、税率同源），不受之后的换套餐
266	// 或套餐定义修改影响。调用方须保证 sub.terms 非空（订阅段创建时即有首条）。
267	func termsForPeriod(sub *subRecord, period Month) PlanTerms {
268		t := sub.terms[0].terms
269		for _, e := range sub.terms {
270			if period.Before(e.effective) {
271				break
272			}
273			t = e.terms
274		}
275		return t
276	}
277	
278	// segmentForBillingLocked 返回账期 period 应使用的订阅段：
279	// 该订阅段在该账期内确有覆盖（开通当月计入，终止当月不计入）。
280	// 完全无订阅覆盖的月份返回 nil。调用时持有 s.mu。
281	func segmentForBillingLocked(acc *account, period Month) *subRecord {
282		if cur := acc.sub; cur != nil && !period.Before(MonthOf(cur.activatedAt)) {
283			return cur
284		}
285		for i := len(acc.history) - 1; i >= 0; i-- {
286			h := acc.history[i]
287			if period.Before(MonthOf(h.activatedAt)) {
288				continue
289			}
290			if period.Before(MonthOf(*h.endedAt)) {
291				return h
292			}
293		}
294		return nil
295	}
296	
297	// SchedulePlanChange 安排账户从下一个 UTC 自然月起改用另一套餐，升级与降级规则相同。
298	//
299	// 成功时返回目标套餐在本次安排时的完整计费条件快照与生效账期（请求被接受时的
300	// 下一个 UTC 自然月），之后修改套餐定义不影响本安排。当前月仍按旧套餐收取完整
301	// 月费并提供完整额度，不按天补差，也不迁移本月已发生的用量。
302	//
303	// 每个账户至多保留一条尚未生效的安排：再次安排同一目标套餐时返回原安排，
304	// 不重新取价（Created 为 false）；安排另一目标套餐则替换原安排，生效月份仍为
305	// 本次请求被接受时的下一月。欠费停用期间也可以安排。
306	//
307	// 账户不存在、尚未开通订阅、开通时刻尚未到达、目标套餐不存在、目标套餐与当前
308	// 生效套餐相同时请求失败，原有安排保持不变。登记取消订阅会清除尚未生效的安排，
309	// 等待取消期间安排换套餐失败（ErrPlanChangeWhileCancelling）。
310	func (s *Service) SchedulePlanChange(accountID, targetPlanID string) (PlanChangeResult, error) {
311		if accountID == "" {
312			return PlanChangeResult{}, invalidf("account id is empty")
313		}
314		if targetPlanID == "" {
315			return PlanChangeResult{}, invalidf("target plan id is empty")
316		}
317		s.mu.Lock()
318		defer s.mu.Unlock()
319	
320		acc, ok := s.accounts[accountID]
321		if !ok {
322			return PlanChangeResult{}, ErrAccountNotFound
323		}
324		now := s.nowUTC()
325		// 先让已到期的安排/取消生效：例如跨月后的首次调用，此时“当前套餐”已是新套餐；
326		// 恰在换套餐生效的月初登记取消，先承认该次切换，取消从再下一月生效。
327		s.settleLocked(acc, now)
328		if acc.sub == nil {
329			return PlanChangeResult{}, ErrSubscriptionNotFound
330		}
331		if now.Before(acc.sub.activatedAt) {
332			return PlanChangeResult{}, ErrSubscriptionNotActivated
333		}
334		if acc.sub.cancelEnd != nil {
335			return PlanChangeResult{}, ErrPlanChangeWhileCancelling
336		}
337	
338		plan, ok := s.plans[targetPlanID]
339		if !ok {
340			return PlanChangeResult{}, ErrPlanNotFound
341		}
342		// 与当前生效套餐的比较同样取当前账期适用的完整条件，
343		// 保证“当前套餐”的判断与状态查询、出账同源。
344		if targetPlanID == termsForPeriod(acc.sub, MonthOf(now)).PlanID {
345			return PlanChangeResult{}, ErrPlanChangeSamePlan
346		}
347	
348		// 已有安排且目标相同：原样返回，不重新取价。
349		if acc.sub.pending != nil && acc.sub.pending.TargetPlanID == targetPlanID {
350			return PlanChangeResult{Created: false, Change: *acc.sub.pending}, nil
351		}
352	
353		change := PlanChange{
354			TargetPlanID:    targetPlanID,
355			Terms:           termsOf(plan),
356			EffectivePeriod: nextMonth(MonthOf(now)),
357		}
358		acc.sub.pending = &change
359		return PlanChangeResult{Created: true, Change: change}, nil
360	}
361	
362	// CancelPlanChange 在安排生效前取消它，取消后账户继续沿用当前套餐。
363	// 没有待生效安排时取消也成功；已生效的切换不会被撤回。
364	// 欠费停用期间也可以取消，取消不清除欠费、不解除停用。
365	// 账户不存在、订阅已终止（含已到终止时刻）时失败。
366	func (s *Service) CancelPlanChange(accountID string) error {
367		if accountID == "" {
368			return invalidf("account id is empty")
369		}
370		s.mu.Lock()
371		defer s.mu.Unlock()
372		acc, ok := s.accounts[accountID]
373		if !ok {
374			return ErrAccountNotFound
375		}
376		// 已到生效月份月初零点的安排视为已生效，不可撤回；已终止订阅段无当前订阅。
377		s.settleLocked(acc, s.nowUTC())
378		if acc.sub == nil {
379			return ErrSubscriptionNotFound
380		}
381		acc.sub.pending = nil
382		return nil
383	}
384	
385	// CancelSubscription 为当前有效订阅登记按月取消。
386	//
387	// 仅当订阅已生效（当前时刻不早于开通时刻）时可取消；欠费停用不妨碍取消，也不
388	// 免除债务。终止时刻为请求时刻的下一个 UTC 自然月月初零点（UTC）：当月照常
389	// 接收用量并按完整月费与额度计费，不按天退款。重复取消始终返回原终止时刻，
390	// 不把期限后移（Cancelled 为 false）。
391	//
392	// 成功时清除尚未生效的换套餐安排；若请求恰在某次换套餐生效的月初，先承认该次
393	// 切换，取消从再下一月生效。等待取消期间拒绝新的换套餐安排。
394	//
395	// 账户不存在、从未开通或当前无有效订阅、开通时刻尚未到达时请求失败。
396	func (s *Service) CancelSubscription(accountID string) (CancelSubscriptionResult, error) {
397		if accountID == "" {
398			return CancelSubscriptionResult{}, invalidf("account id is empty")
399		}
400		s.mu.Lock()
401		defer s.mu.Unlock()
402	
403		acc, ok := s.accounts[accountID]
404		if !ok {
405			return CancelSubscriptionResult{}, ErrAccountNotFound
406		}
407		now := s.nowUTC()
408		// 先补齐到期状态：恰在月初时先承认到期换套餐，终止时刻取再下一月。
409		s.settleLocked(acc, now)
410		if acc.sub == nil {
411			return CancelSubscriptionResult{}, ErrSubscriptionNotFound
412		}
413		if now.Before(acc.sub.activatedAt) {
414			return CancelSubscriptionResult{}, ErrSubscriptionNotActivated
415		}
416	
417		// 重复取消：原样返回原终止时刻，不后移期限。
418		if acc.sub.cancelEnd != nil {
419			return CancelSubscriptionResult{
420				Cancelled:    false,
421				Cancellation: SubscriptionCancellation{EndAt: *acc.sub.cancelEnd},
422			}, nil
423		}
424	
425		// 登记取消清除尚未生效的换套餐安排（撤回取消也不恢复它）。
426		acc.sub.pending = nil
427		end := nextMonth(MonthOf(now)).Start()
428		acc.sub.cancelEnd = &end
429		return CancelSubscriptionResult{
430			Cancelled:    true,
431			Cancellation: SubscriptionCancellation{EndAt: end},
432		}, nil
433	}
434	
435	// UndoCancelSubscription 在取消生效前撤回按月取消安排，撤回后订阅继续有效。
436	// 有效订阅没有取消安排时撤回也成功；撤回不恢复登记取消时被清除的换套餐安排。
437	// 终止时刻已到（订阅已终止）后撤回失败（ErrSubscriptionNotFound）；
438	// 账户不存在或从未开通时同样失败。
439	func (s *Service) UndoCancelSubscription(accountID string) error {
440		if accountID == "" {
441			return invalidf("account id is empty")
442		}
443		s.mu.Lock()
444		defer s.mu.Unlock()
445		acc, ok := s.accounts[accountID]
446		if !ok {
447			return ErrAccountNotFound
448		}
449		// 到达终止时刻后订阅已终止：撤回失败。
450		s.settleLocked(acc, s.nowUTC())
451		if acc.sub == nil {
452			return ErrSubscriptionNotFound
453		}
454		acc.sub.cancelEnd = nil
455		return nil
456	}
457	
458	// RecordEvent 上报一条用量事件。
459	//
460	// 事件按发生时刻归入 UTC 自然月账期；事件发生时刻必须属于某段实际订阅期间
461	// （开通时刻计入、终止时刻不计入），空档期间与晚于当前时刻的事件被拒绝。
462	// 订阅终止后仍可补报旧订阅期间且尚未出账的用量。
463	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计——
464	// 即使发生在取消、重新开通之后也成功；相同标识但时刻或数量不同返回
465	// ErrEventConflict。
466	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新增事件；
467	// 但此前已接收事件的完全相同重报始终成功。
468	func (s *Service) RecordEvent(e Event) (EventResult, error) {
469		if e.AccountID == "" {
470			return EventResult{}, invalidf("account id is empty")
471		}
472		if e.EventID == "" {
473			return EventResult{}, invalidf("event id is empty")
474		}
475		if e.Quantity < 0 {
476			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
477		}
478		if e.At.IsZero() {
479			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
480		}
481		at := e.At.UTC()
482	
483		s.mu.Lock()
484		defer s.mu.Unlock()
485	
486		acc, ok := s.accounts[e.AccountID]
487		if !ok {
488			return EventResult{}, ErrAccountNotFound
489		}
490	
491		now := s.nowUTC()
492		// 进入即补齐已到期的换套餐/取消，保证并发下各操作观察到一致的分段状态。
493		s.settleLocked(acc, now)
494	
495		// 从未开通订阅的账户没有任何订阅段。
496		if acc.sub == nil && len(acc.history) == 0 {
497			return EventResult{}, ErrSubscriptionNotFound
498		}
499	
500		// 去重优先：完全相同的重报即使发生在出账后、停用期间、取消或重新开通
501		// 之后也返回成功。
502		if prev, ok := acc.events[e.EventID]; ok {
503			if !prev.at.Equal(at) || prev.qty != e.Quantity {
504				return EventResult{}, ErrEventConflict
505			}
506			return EventResult{Accepted: false, Period: prev.period}, nil
507		}
508	
509		if at.After(now) {
510			return EventResult{}, ErrEventInFuture
511		}
512		// 事件发生时刻必须落在某段实际订阅期间：[activatedAt, end)。
513		if activeSegmentAtLocked(acc, at) == nil {
514			return EventResult{}, ErrEventBeforeSubscription
515		}
516	
517		period := MonthOf(at)
518		if _, billed := acc.bills[period]; billed {
519			return EventResult{}, ErrMonthBilled
520		}
521		if s.isSuspendedLocked(acc, now) {
522			return EventResult{}, ErrSuspended
523		}
524	
525		total, ok := addNonNeg(acc.usage[period], e.Quantity)
526		if !ok {
527			return EventResult{}, ErrOverflow
528		}
529		// 所有校验通过后才落库：失败不消耗事件标识。
530		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
531		acc.usage[period] = total
532		return EventResult{Accepted: true, Period: period}, nil
533	}
534	
535	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
536	// 只能为某段订阅实际覆盖的、且已经结束的月份生成账单：开通当月计入、终止
537	// 当月（终止时刻所在月）不计入该段，完全无订阅的空档月份出账失败。
538	// 取消订阅不自动出账；终止后旧订阅覆盖的已结束月份仍可出账，使用各月当时
539	// 锁定的条件。重复调用得到同一账单；出账后金额与用量明细固定。
540	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
541		if accountID == "" {
542			return Bill{}, invalidf("account id is empty")
543		}
544		if period.Month < time.January || period.Month > time.December {
545			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
546		}
547		s.mu.Lock()
548		defer s.mu.Unlock()
549	
550		acc, ok := s.accounts[accountID]
551		if !ok {
552			return Bill{}, ErrAccountNotFound
553		}
554		if existing, ok := acc.bills[period]; ok {
555			return existing.bill, nil
556		}
557	
558		now := s.nowUTC()
559		// 补齐到期换套餐/取消（条件历史与分段），随后按账期取覆盖该月的订阅段中
560		// 当时适用的条件：即使已重新开通或先出新月份账单再补旧月份账单，历史账单
561		// 也不会被后来的订阅覆盖。
562		s.settleLocked(acc, now)
563	
564		if acc.sub == nil && len(acc.history) == 0 {
565			return Bill{}, ErrSubscriptionNotFound
566		}
567		if period.End().After(now) {
568			return Bill{}, ErrBillMonthNotEnded
569		}
570	
571		sub := segmentForBillingLocked(acc, period)
572		if sub == nil {
573			// 早于首段开通，或处于两段订阅之间的空档。
574			return Bill{}, ErrBillBeforeSubscription
575		}
576	
577		terms := termsForPeriod(sub, period)
578		bill, err := buildBill(accountID, period, terms, acc.usage[period])
579		if err != nil {
580			return Bill{}, err
581		}
582		acc.bills[period] = &billRecord{bill: bill}
583		return bill, nil
584	}
585	
586	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
587	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
588		if accountID == "" {
589			return Bill{}, invalidf("account id is empty")
590		}
591		s.mu.Lock()
592		defer s.mu.Unlock()
593		acc, ok := s.accounts[accountID]
594		if !ok {
595			return Bill{}, ErrAccountNotFound
596		}
597		rec, ok := acc.bills[period]
598		if !ok {
599			return Bill{}, ErrBillNotFound
600		}
601		return rec.bill, nil
602	}
603	
604	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
605	// 付款标识在同一账户内去重：相同账单和金额的重报仍成功，但本次不再登记
606	// （Registered 为 false），也不再次增加已付金额；返回的付款内容、账单余额与
607	// 付清状态均为该笔付款首次成功登记完成时的历史结果，不随后续付款或账单当前
608	// 状态变化（例如账单后来已结清，重报早先的部分付款仍返回当时的未清余额与
609	// 未付清）。账单查询与账户状态中的余额始终反映当前状态，不受重报影响。
610	// 相同标识但账期或金额不同返回 ErrPaymentConflict：即使原账单已结清，或改指
611	// 向的账期还没有账单，也按冲突处理而非当作新付款。失败不消耗付款标识。
612	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
613		if accountID == "" {
614			return PaymentResult{}, invalidf("account id is empty")
615		}
616		if paymentID == "" {
617			return PaymentResult{}, invalidf("payment id is empty")
618		}
619		if amount <= 0 {
620			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
621		}
622		s.mu.Lock()
623		defer s.mu.Unlock()
624	
625		acc, ok := s.accounts[accountID]
626		if !ok {
627			return PaymentResult{}, ErrAccountNotFound
628		}
629		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
630		if prev, ok := acc.payments[paymentID]; ok {
631			if prev.period != period || prev.amount != amount {
632				return PaymentResult{}, ErrPaymentConflict
633			}
634			// 完全相同的重报仍成功，但不再次登记、不改变账单：
635			// 返回这笔付款首次成功登记完成时的余额与付清状态，
636			// 不受账单后续收款、当前余额或停用/恢复状态影响。
637			return PaymentResult{
638				Registered:  false,
639				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
640				BillBalance: prev.balance,
641				Settled:     prev.settled,
642			}, nil
643		}
644	
645		rec, ok := acc.bills[period]
646		if !ok {
647			return PaymentResult{}, ErrBillNotFound
648		}
649	
650		if amount > rec.bill.Balance {
651			return PaymentResult{}, ErrPaymentExceedsBalance
652		}
653	
654		paid, ok := addNonNeg(rec.bill.Paid, amount)
655		if !ok {
656			return PaymentResult{}, ErrOverflow
657		}
658		rec.bill.Paid = paid
659		rec.bill.Balance -= amount
660		if rec.bill.Balance == 0 {
661			rec.bill.Settled = true
662		}
663		// 保存首次登记完成时的历史结果，供完全相同重报原样返回。
664		acc.payments[paymentID] = paymentRecord{
665			period:  period,
666			amount:  amount,
667			balance: rec.bill.Balance,
668			settled: rec.bill.Settled,
669		}
670	
671		return PaymentResult{
672			Registered:  true,
673			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
674			BillBalance: rec.bill.Balance,
675			Settled:     rec.bill.Settled,
676		}, nil
677	}
678	
679	// MonthlyUsage 返回账户某账期的累计用量；无任何用量时返回 0。
680	func (s *Service) MonthlyUsage(accountID string, period Month) (Usage, error) {
681		if accountID == "" {
682			return Usage{}, invalidf("account id is empty")
683		}
684		s.mu.Lock()
685		defer s.mu.Unlock()
686		acc, ok := s.accounts[accountID]
687		if !ok {
688			return Usage{}, ErrAccountNotFound
689		}
690		// 与其他入口保持一致：顺带让已到期的换套餐/取消生效。
691		s.settleLocked(acc, s.nowUTC())
692		return Usage{Period: period, Total: acc.usage[period]}, nil
693	}
694	
695	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
696	func (s *Service) Status(accountID string) (AccountStatus, error) {
697		if accountID == "" {
698			return AccountStatus{}, invalidf("account id is empty")
699		}
700		s.mu.Lock()
701		defer s.mu.Unlock()
702		acc, ok := s.accounts[accountID]
703		if !ok {
704			return AccountStatus{}, ErrAccountNotFound
705		}
706	
707		now := s.nowUTC()
708		// 查询即让已到期安排/取消生效：月初零点或终止时刻之后无需上报用量或出账，
709		// 当前条件与订阅状态立即更新。
710		s.settleLocked(acc, now)
711	
712		// 订阅是否生效以实际开通时刻为界：提前登记、开通时刻尚未到达的订阅仍
713		// 保存在 acc.sub 中（再次开通、安排换套餐、登记取消均按已有订阅的规则
714		// 处理），但查询时刻不显示为有效订阅。到达开通时刻即生效，不按开通月份
715		// 提前生效；时刻按同一瞬间比较，使用带时区的时间结果一致。
716		active := acc.sub != nil && !now.Before(acc.sub.activatedAt)
717	
718		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
719		for m := range acc.usage {
720			periodSet[m] = struct{}{}
721		}
722		for m := range acc.bills {
723			periodSet[m] = struct{}{}
724		}
725		periods := make([]Month, 0, len(periodSet))
726		for m := range periodSet {
727			periods = append(periods, m)
728		}
729		sortMonths(periods)
730	
731		st := AccountStatus{
732			AccountID:    accountID,
733			Subscribed:   active,
734			Suspended:    s.isSuspendedLocked(acc, now),
735			MonthlyUsage: make([]Usage, 0, len(periods)),
736			Bills:        make([]BillSummary, 0, len(acc.bills)),
737		}
738		// 仅实际生效的订阅才展示当前套餐条件、待换套餐安排与已安排终止时刻；
739		// 等待开通期间这些字段均为零值（查询不删除也不提前激活已登记订阅）。
740		if active {
741			// 当前条件与历史出账取自同一份条件时间线：月初零点 settleLocked
742			// 追加新快照后，这里直接拿到安排时锁定的完整条件，无需另行同步。
743			st.CurrentTerms = termsForPeriod(acc.sub, MonthOf(now))
744			if acc.sub.pending != nil {
745				pending := *acc.sub.pending
746				st.PendingChange = &pending
747			}
748			if acc.sub.cancelEnd != nil {
749				end := *acc.sub.cancelEnd
750				st.ScheduledEnd = &end
751			}
752		}
753		for _, m := range periods {
754			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
755		}
756		for _, m := range periods {
757			if rec, ok := acc.bills[m]; ok {
758				b := rec.bill
759				st.Bills = append(st.Bills, BillSummary{
760					Period:   m,
761					TotalDue: b.TotalDue,
762					Paid:     b.Paid,
763					Balance:  b.Balance,
764					Settled:  b.Settled,
765					DueAt:    b.DueAt,
766				})
767			}
768		}
769		return st, nil
770	}
771	
772	// isSuspendedLocked 报告账户当前是否停用：
773	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
774	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
775		for _, rec := range acc.bills {
776			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
777				return true
778			}
779		}
780		return false
781	}
782	
783	func sortMonths(ms []Month) {
784		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
785	}
786	
787	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
788	func addNonNeg(a, b int64) (int64, bool) {
789		if a > maxInt64-b {
790			return 0, false
791		}
792		return a + b, true
793	}
794	
795	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
796	func mulNonNeg(a, b int64) (int64, bool) {
797		if a == 0 || b == 0 {
798			return 0, true
799		}
800		if a > maxInt64/b {
801			return 0, false
802		}
803		return a * b, true
804	}
805	
806	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
807	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
808		overageUnits := int64(0)
809		if totalUsage > t.IncludedUnits {
810			overageUnits = totalUsage - t.IncludedUnits
811		}
812		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
813		if !ok {
814			return Bill{}, ErrOverflow
815		}
816		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
817		if !ok {
818			return Bill{}, ErrOverflow
819		}
820		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
821		if !ok {
822			return Bill{}, ErrOverflow
823		}
824		totalDue, ok := addNonNeg(subtotal, tax)
825		if !ok {
826			return Bill{}, ErrOverflow
827		}
828		b := Bill{
829			AccountID:     accountID,
830			Period:        period,
831			Terms:         t,
832			TotalUsage:    totalUsage,
833			IncludedUnits: t.IncludedUnits,
834			OverageUnits:  overageUnits,
835			MonthlyFee:    t.MonthlyFee,
836			OverageFee:    overageFee,
837			Tax:           tax,
838			TotalDue:      totalDue,
839			Paid:          0,
840			Balance:       totalDue,
841			Settled:       totalDue == 0,
842			DueAt:         period.End().AddDate(0, 0, 7),
843		}
844		return b, nil
845	}
846	
847	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
848	// 拆分商和余数计算以避免乘积溢出 int64。
849	func rateAmount(amount, rate int64) (int64, bool) {
850		const den = 10000
851		q, r := amount/den, amount%den
852		qr, ok := mulNonNeg(q, rate)
853		if !ok {
854			return 0, false
855		}
856		rr, ok := mulNonNeg(r, rate)
857		if !ok {
858			return 0, false
859		}
860		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
861		add, ok := addNonNeg(qr, (rr+den/2)/den)
862		if !ok {
863			return 0, false
864		}
865		return add, true
866	}
867

